sub dbg {
	print @_ if $debug;
}

sub send {
	my ($ch, $msg) = @_;
	my $r = $json->encode($msg);
	&dbg("### $0: sending '$r' on $ch\n");
	if ($ch eq "sync") {
		print $out "$r\n";
	} else {
		print $aout "$r\n";
	}
}

sub receive {
	while (<$in>) {
	       	if ($obj = $json->incr_parse($_)) {
			&dbg(Dumper($obj));
			return $obj;
		}
	}
	exit;
}

sub areceive {
	while (<$ain>) {
	       	if ($obj = $json->incr_parse($_)) {
			&dbg(Dumper($obj));
			return $obj;
		}
	}
	exit;
}

sub send_ret {
	my $arg = shift || 0;
	&send("sync", { return => $arg});
}

sub send_intr {
	return unless ($CTL & 1);

	if (($STS & 1) && !$pend_intr) {
		#&send("async", { "raise-irq" => 1 });
		#&areceive;
		$pend_intr = 1;
		&ualarm(10000);
	}
}

sub clear_intr {
	if ($pend_intr) {
		&send("sync", { "lower-irq" => 1 });
		&receive;
		$pend_intr = 0;
	}
}

sub new_value {
	if (!$pend_intr) {
		$RBR++;
		if ($RBR > 90) {
			$RBR = 65;
		}
		$STS |= 1;
		&send_intr;
	}
}

