+			ioaddr ctl = ce_d->iCTL;
+			natb val = inputb(ctl);
+			outputb(val | 0x1, ctl);
+		}
+	}
+}
+
+void enable_intr(natl id)
+{
+	des_ce *ce_d = &array_ce[id];
+	ioaddr ctl = ce_d->iCTL;
+	natb val = inputb(ctl);
+	outputb(val | 0x1, ctl);
+}
+
+void disable_intr(natl id)
+{
+	des_ce *ce_d = &array_ce[id];
+	ioaddr ctl = ce_d->iCTL;
+	natb val = inputb(ctl);
+	outputb(val & ~0x1, ctl);
+}
+
 }

 /// Corpo del processo esterno delle periferiche CE
 extern "C" void estern_ce(natq id)
 {
-// ( SOLUZIONE 2025-09-10
-//   SOLUZIONE 2025-09-10 )
+	for (;;) {
+		ce::disable_intr(id);
+		des_ce *ce_d = &array_ce[id];
+		sem_wait(ce_d->mutex);
+		if (ce_d->cur != 0xFFFFFFFF) {
+			des_ce_tr *t = &ce_d->tr[ce_d->cur];
+			if (t->buf != nullptr && t->quanti > 0) {
+				natb c = inputb(ce_d->iRBR);
+				*t->buf = c;
+				t->buf++;
+				t->quanti--;
+				if (t->quanti == 0) {
+					natl next_tr = t->next;
+					ce_d->cur = next_tr;
+					sem_signal(ce_d->sync);
+					if (ce_d->waiting > 0) {
+						ce_d->waiting--;
+						sem_signal(ce_d->sync);
+					}
+					if (next_tr != 0xFFFFFFFF) {
+						ce::enable_intr(id);
+					}
+				} else {
+					ce::enable_intr(id);
+				}
+			} else {
+				ce::enable_intr(id);
+			}
+		} else {
+			ce::enable_intr(id);
+		}
+		sem_signal(ce_d->mutex);
+		wfi();
+	}
 }

